#include <cctype>
#include <iostream>
#include <string>

int main() {
    std::string title;
    int number = 0;
    std::getline(std::cin, title);
    std::cin >> number >> std::ws;

    for (char& c : title) {
        c = static_cast<char>(std::toupper(static_cast<unsigned char>(c)));
    }
    std::cout << title << '\n';

    std::string comment;
    while (std::getline(std::cin, comment)) {
        std::cout << number << ". " << comment << '\n';
        ++number;
    }
    return 0;
}
